1. import careConfig from "@careConfig";
2. 
3. import { RESULTS_PER_PAGE_LIMIT } from "@/common/constants";
4. 
5. import {
6.   ApiCallOptions,
7.   ApiRoute,
8.   HTTPError,
9.   PaginatedResponse,
10. } from "@/Utils/request/types";
11. import { getResponseBody, makeHeaders, makeUrl } from "@/Utils/request/utils";
12. import { sleep } from "@/Utils/utils";
13. 
14. export async function callApi<Route extends ApiRoute<unknown, unknown>>(
15.   { baseUrl, path, method, noAuth, defaultQueryParams }: Route,
16.   options?: ApiCallOptions<Route>,
17. ): Promise<Route["TRes"]> {
18.   const url = `${baseUrl ?? careConfig.apiUrl}${makeUrl(
19.     path,
20.     {
21.       ...(defaultQueryParams ?? {}),
22.       ...options?.queryParams,
23.     },
24.     options?.pathParams,
25.   )}`;
26. 
27.   const isFormData = options?.body instanceof FormData;
28. 
29.   const fetchOptions: RequestInit = {
30.     method,
31.     headers: makeHeaders(noAuth ?? false, options?.headers, isFormData),
32.     signal: options?.signal,
33.   };
34. 
35.   if (options?.body) {
36.     if (isFormData) {
37.       fetchOptions.body = options.body as FormData;
38.     } else {
39.       fetchOptions.body = JSON.stringify(options.body);
40.     }
41.   }
42. 
43.   let res: Response;
44. 
45.   try {
46.     res = await fetch(url, fetchOptions);
47.   } catch {
48.     throw new Error("Network Error");
49.   }
50. 
51.   const data = await getResponseBody<Route["TRes"]>(res);
52. 
53.   if (!res.ok) {
54.     const isSilent =
55.       typeof options?.silent === "function"
56.         ? options.silent(res)
57.         : (options?.silent ?? false);
58. 
59.     throw new HTTPError({
60.       message: "Request Failed",
61.       status: res.status,
62.       silent: isSilent,
63.       cause: data as unknown as Record<string, unknown>,
64.     });
65.   }
66. 
67.   return data;
68. }
69. 
70. /**
71.  * Creates a TanStack Query compatible query function.
72.  *
73.  * Example:
74.  * ```tsx
75.  * const { data, isLoading } = useQuery({
76.  *   queryKey: ["prescription", consultationId],
77.  *   queryFn: query(MedicineRoutes.prescription, {
78.  *     pathParams: { consultationId },
79.  *     queryParams: {
80.  *       limit: 10,
81.  *       offset: 0,
82.  *     },
83.  *   }),
84.  * });
85.  * ```
86.  */
87. export default function query<Route extends ApiRoute<unknown, unknown>>(
88.   route: Route,
89.   options?: ApiCallOptions<Route>,
90. ) {
91.   return ({ signal }: { signal: AbortSignal }) => {
92.     return callApi(route, { ...options, signal });
93.   };
94. }
95. 
96. /**
97.  * Creates a debounced TanStack Query compatible query function.
98.  *
99.  * Example:
100.  * ```tsx
101.  * const { data, isLoading } = useQuery({
102.  *   queryKey: ["patient-search", facilityId, search],
103.  *   queryFn: query.debounced(patientsApi.search, {
104.  *     pathParams: { facilityId },
105.  *     queryParams: { limit: 10, offset: 0, search },
106.  *   }),
107.  * });
108.  * ```
109.  *
110.  * The debounced query leverages TanStack Query's built-in cancellation through
111.  * `AbortSignal`. Here's how it works:
112.  *
113.  * 1. When a new query is triggered, TanStack Query automatically creates an
114.  * `AbortSignal`
115.  * 2. If a new query starts before the debounce delay finishes:
116.  *    - The previous signal is aborted automatically by TanStack Query
117.  *    - The previous `sleep` promise is cancelled
118.  *    - A new debounce timer starts
119.  *
120.  * No explicit cleanup is needed because:
121.  * - The `AbortSignal` is passed through to the underlying `fetch` call
122.  * - When aborted, both the `sleep` promise and the fetch request are cancelled automatically
123.  * - TanStack Query handles the abortion and cleanup of previous in-flight requests
124.  */
125. const debouncedQuery = <Route extends ApiRoute<unknown, unknown>>(
126.   route: Route,
127.   options?: ApiCallOptions<Route> & { debounceInterval?: number },
128. ) => {
129.   return async ({ signal }: { signal: AbortSignal }) => {
130.     await sleep(options?.debounceInterval ?? 500);
131.     return query(route, { ...options })({ signal });
132.   };
133. };
134. query.debounced = debouncedQuery;
135. 
136. /**
137.  * Creates a TanStack Query compatible paginated query function.
138.  *
139.  * This function is useful for fetching paginated data from an API.
140.  * It will fetch all pages of data and return a single array of results.
141.  *
142.  * To disable pagination, set the `maxPages` option to `1`.
143.  * Leaving it unset will fetch all pages.
144.  *
145.  * Example:
146.  * ```tsx
147.  * const { data, isLoading } = useQuery({
148.  *   queryKey: ["patient-search", facilityId, search],
149.  *   queryFn: query.paginated(patientsApi.search, {
150.  *     pathParams: { facilityId },
151.  *     queryParams: { limit: 10, offset: 0, search },
152.  *   }),
153.  * });
154.  * ```
155.  */
